    @Test func gateTableExhaustively() throws {
        let fx = try fixture("gate.json")
        let cases = try #require(fx["cases"] as? [[String: Any]])
        // Exhaustive: every context (2 lock × 3 role × 2 pin) × every kind —
        // derived from the enum so adding a MutationKind extends the pin.
        #expect(cases.count == 2 * 3 * 2 * MutationKind.allCases.count)
        // And every kind the fixture exercises must exist in this port.
        let fixtureKinds = Set(cases.compactMap { $0["kind"] as? String })
        #expect(fixtureKinds == Set(MutationKind.allCases.map(\.rawValue)))
        for c in cases {
            let kindRaw = try #require(c["kind"] as? String)
            let kind = try #require(MutationKind(rawValue: kindRaw))
            let role = (c["role"] as? String).flatMap(HouseholdRole.init(rawValue:))
            let ctx = GateContext(
                managedLockOptions: try #require(c["managedLockOptions"] as? Bool),
                role: role,
                hasPin: try #require(c["hasPin"] as? Bool)
            )
            let verdict = Gate.gateMutation(kind, ctx: ctx)
            let expected = try #require(c["verdict"] as? [String: Any])
            let label =
                "\(kind.rawValue) lock=\(ctx.managedLockOptions) role=\(String(describing: role)) pin=\(ctx.hasPin)"
            if expected["allowed"] as? Bool == true {
                let requiresPin = try #require(expected["requiresPin"] as? Bool)
                #expect(verdict == .allowed(requiresPin: requiresPin), "\(label)")
            } else {
                let reasonRaw = try #require(expected["reason"] as? String)
                let reason = try #require(
                    MutationVerdict.RefusalReason(rawValue: reasonRaw))
                #expect(verdict == .refused(reason: reason), "\(label)")
            }
        }
    }

    /// Leaving a household never received: gated as the fixture field says,
    /// so on that kind's rows it is refused under a managed lock and goes
    /// otherwise — any role, PIN or not — in every delay phase.
    @Test func subscriptionGatedAsTheFixtureSays() throws {
        let fx = try fixture("gate.json")
        #expect(fx["subscriptionGatedAs"] as? String == Gate.subscriptionGatedAs.rawValue)
        let k = Gate.subscriptionGatedAs
        let ctx = { (role: HouseholdRole?, pin: Bool) in GateContext(managedLockOptions: false, role: role, hasPin: pin) }
        #expect(Delay.decide(.kind(k), ctx: ctx(.child, true), phase: .idle) == .refused(.childDevice))
        #expect(Delay.decide(.kind(k), ctx: ctx(.guardian, true), phase: .idle) == .pin)
        #expect(Delay.decide(.kind(k), ctx: ctx(.guardian, false), phase: .idle) == .go)
        #expect(Delay.decide(.kind(k), ctx: ctx(nil, false), phase: .idle) == .go, "creating, no household yet")
        #expect(!Delay.needsWait(.kind(k), .idle), "no wait")
    }

    @Test func leaveJoinPlaceholderGatedAsTheFixtureSays() throws {
        let fx = try fixture("gate.json")
        #expect(fx["leaveJoinPlaceholderGatedAs"] as? String == Gate.leaveJoinPlaceholderGatedAs.rawValue)
        let rows = try #require(fx["cases"] as? [[String: Any]]).filter {
            $0["kind"] as? String == Gate.leaveJoinPlaceholderGatedAs.rawValue
        }
        #expect(rows.count == 12)
        for c in rows {
            let locked = try #require(c["managedLockOptions"] as? Bool)
            let ctx = GateContext(
                managedLockOptions: locked,
                role: (c["role"] as? String).flatMap(HouseholdRole.init(rawValue:)),
                hasPin: try #require(c["hasPin"] as? Bool))
            for phase in [DelayPhase.off, .idle, .waiting, .open] {
                #expect(
                    Delay.decide(.leaveJoinPlaceholder, ctx: ctx, phase: phase)
                        == (locked ? .refused(.managedLocked) : .go), "\(c) \(phase)")
            }
        }
    }

    @Test func delayTable() throws {
        let fx = try fixture("delay.json")
        #expect(fx["delayMinutesAllowed"] as? [Int] == Delay.minutesAllowed)
        #expect((fx["windowMs"] as? NSNumber)?.int64Value == Delay.windowMs)
        #expect(fx["shortenDelayGatedAs"] as? String == Delay.shortenDelayGatedAs.rawValue)
        let joinKind = try #require(
            (fx["joinHouseholdWaitsAs"] as? String).flatMap(MutationKind.init(rawValue:)))
        #expect(joinKind == Delay.joinHouseholdWaitsAs)
        #expect(Delay.needsWait(.kind(joinKind), .idle))
        func request(_ raw: Any?) -> DelayRequest? {
            ((raw as? [String: Any])?["at"] as? NSNumber).map { DelayRequest(at: $0.int64Value) }
        }
        let evaluate = try #require(fx["evaluate"] as? [[String: Any]])
        let needsWait = try #require(fx["needsWait"] as? [[String: Any]])
        let delayChange = try #require(fx["delayChange"] as? [[String: Any]])
        #expect(evaluate.count + needsWait.count + delayChange.count == 224)
        for c in evaluate {
            let name = c["name"] as? String ?? "?"
            let expected = try #require(c["result"] as? [String: Any])
            let got = Delay.evaluate(
                delayMinutes: try #require(c["delayMinutes"] as? Int),
                request: request(c["request"]),
                now: try #require(c["now"] as? NSNumber).int64Value)
            #expect(got.phase.rawValue == expected["phase"] as? String, "\(name)")
            #expect(got.remainingMs == (expected["remainingMs"] as? NSNumber)?.int64Value, "\(name)")
            #expect(got.request == request(expected["request"]), "\(name)")
        }
        for c in needsWait {
            let action = try #require((c["action"] as? String).flatMap(DelayAction.init(rawValue:)))
            let phase = try #require((c["phase"] as? String).flatMap(DelayPhase.init(rawValue:)))
            #expect(Delay.needsWait(action, phase) == c["needsWait"] as? Bool, "\(c)")
        }
        for c in delayChange {
            let action = Delay.changeAction(
                from: try #require(c["fromMinutes"] as? Int), to: try #require(c["toMinutes"] as? Int))
            #expect(action == (c["action"] as? String).flatMap(DelayAction.init(rawValue:)), "\(c)")
            let phase = try #require((c["phase"] as? String).flatMap(DelayPhase.init(rawValue:)))
            #expect((action.map { Delay.needsWait($0, phase) } ?? false) == c["needsWait"] as? Bool, "\(c)")
        }
    }

    @Test func sanitizeCases() throws {
        let fx = try fixture("sanitize.json")
        for c in try #require(fx["cases"] as? [[String: Any]]) {
            let name = c["name"] as? String ?? "?"
            let result = Household.sanitize(c["raw"])
            if c["ok"] as? Bool == true {
                guard case .success(let state) = result else {
